<script setup lang="ts">
import { ref, watch } from 'vue';
import { showToast } from './toast';
type Order = {id:number;campaign_id:number;request_id:string;amount_snapshot:string;status:string};
const props=defineProps<{token:string;username:string;target:{id:number;sequence:number}|null}>();
const emit=defineEmits<{cancelled:[]}>();
const orderId=ref(''), order=ref<Order|null>(null), busy=ref(false), error=ref(''), searched=ref(false);
async function api(path:string,method='GET'):Promise<Order>{let response:Response;try{response=await fetch('/api/v1'+path,{method,headers:{Authorization:`Bearer ${props.token}`}});}catch{throw new Error('无法连接服务，请检查后端是否启动。');}const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'操作失败，请重试。');return data as Order;}
async function findOrder(){if(!/^[1-9]\d*$/.test(orderId.value)){error.value='请输入有效的订单编号。';return;}busy.value=true;error.value='';order.value=null;searched.value=true;try{order.value=await api(`/voucher-orders/${orderId.value}`);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function cancel(){if(!order.value||!confirm('确定取消订单并释放库存吗？'))return;busy.value=true;error.value='';try{order.value=await api(`/voucher-orders/${order.value.id}/cancel`,'POST');const key=`nexusops_voucher_requests_${props.username}`;try{const data=JSON.parse(localStorage.getItem(key)||'{}');if(data[order.value.campaign_id]===order.value.request_id){delete data[order.value.campaign_id];localStorage.setItem(key,JSON.stringify(data));}}catch{/* 不影响订单取消结果。 */}showToast('订单已取消');emit('cancelled');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function reset(){orderId.value='';order.value=null;error.value='';searched.value=false;}
watch(()=>props.target, value=>{if(value){orderId.value=String(value.id);void findOrder();}},{immediate:true});
</script>
<template>
<section class="orders">
  <form class="filters" @submit.prevent="findOrder"><label>订单编号<input v-model.trim="orderId" inputmode="numeric" placeholder="请输入订单编号"></label><div class="filter-actions"><button type="button" :disabled="busy" @click="reset">重置</button><button class="primary" :disabled="busy">查询</button></div></form>
  <div class="panel"><div class="toolbar"><h2>优惠券订单</h2></div><p v-if="error" class="error" role="alert">{{ error }}</p><div class="table-wrap"><table><thead><tr><th>订单编号</th><th>活动编号</th><th>订单金额</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="order"><td>{{ order.id }}</td><td>{{ order.campaign_id }}</td><td>¥ {{ Number(order.amount_snapshot).toFixed(2) }}</td><td><span class="status" :class="order.status">{{ order.status==='created'?'待支付':order.status==='cancelled'?'已取消':order.status }}</span></td><td><button v-if="order.status==='created'" class="link" :disabled="busy" @click="cancel">取消订单</button><span v-else>—</span></td></tr><tr v-else><td colspan="5" class="empty">{{ busy?'查询中…':searched && error?'查询失败，请重试':'请输入订单编号查询' }}</td></tr></tbody></table></div></div>
</section>
</template>
<style scoped>
.orders{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:2px;background:#f0f2f5;padding:2px;color:#172233;font-size:14px}.filters,.panel{background:#fff;border:2px solid #d8e0ec;padding:12px}.filters,.filters label,.filter-actions,.toolbar{display:flex;align-items:center;gap:15px}.filters{min-height:68px}.filters label{white-space:nowrap}.filters input{width:270px;height:40px;padding:0 13px;border:1px solid #dce3ed;border-radius:6px;font:inherit}.filters input::placeholder{color:#b8c2cf}.filter-actions{margin-left:auto;gap:10px}button{box-sizing:border-box;min-width:72px;height:40px;display:inline-flex;align-items:center;justify-content:center;padding:0 16px;border:1px solid #dce3ed;border-radius:5px;background:#fff;color:#334155;font:inherit;white-space:nowrap;cursor:pointer}.orders button.primary{width:auto;margin:0;position:static;background:#5267ff;border-color:#5267ff;color:white;font-weight:400;letter-spacing:normal}.orders button:hover:not(:disabled){border-color:#5267ff;color:#5267ff}.orders button.primary:hover:not(:disabled){background:#4054ed;color:#fff}button:disabled{opacity:.45;cursor:not-allowed}.panel{flex:1;min-height:280px;display:flex;flex-direction:column}.toolbar{min-height:48px}.toolbar h2{font-size:18px;margin:0}.hint{font-size:13px;color:#718096;margin:0 0 12px}.error{color:#ba3e3e;font-size:13px}.table-wrap{flex:1;min-height:160px;overflow:auto;border:1px solid #dce4ef;border-radius:5px}table{width:100%;min-width:650px;border-collapse:collapse;text-align:center}th,td{height:50px;padding:10px 12px;border-bottom:1px solid #dce4ef}th{background:#eef3f9;color:#344054;font-weight:600}.empty{height:100px;color:#8190a3}.status{display:inline-block;padding:4px 9px;border-radius:4px;background:#f1f3f5;color:#788594}.status.created{background:#fff8e8;color:#a77916}.orders button.link{min-width:0;height:auto;padding:5px 7px;border:0;color:#5267ff}.orders button:focus-visible,.orders input:focus-visible{outline:2px solid #5267ff;outline-offset:2px}@media(max-width:700px){.filters{flex-wrap:wrap}.filters label{width:100%}.filters input{flex:1;min-width:0}.panel{min-height:360px}}
</style>
